-- Exact inspected production defaults/checks/FKs, for isolated synthetic tests only.
drop table internal_academic.technical_manual_banese_reissue_jobs;
create table internal_academic.technical_manual_banese_reissue_jobs (
 "id" uuid not null default gen_random_uuid(),
 "receivable_id" uuid not null,
 "matricula_id" uuid not null,
 "turma_id" uuid not null,
 "cycle_number" smallint not null,
 "cycle_request_id" uuid not null,
 "expected_item_count" integer not null,
 "recovery_request_id" uuid not null,
 "original_actor_id" uuid not null,
 "canceled_nosso_numero" text not null,
 "convenio" text not null,
 "agency" text not null,
 "expected_amount" numeric(14,2) not null,
 "expected_due_date" date not null,
 "receivable_fingerprint" text not null,
 "expected_receivable_updated_at" timestamp with time zone not null,
 "lease_token" uuid not null default gen_random_uuid(),
 "lease_valid_until" timestamp with time zone not null,
 "status" text not null default 'FENCED'::text,
 "cancel_mutation_intent_at" timestamp with time zone,
 "cancel_mutation_intent_count" integer not null default 0,
 "reset_completed_at" timestamp with time zone,
 "created_at" timestamp with time zone not null default now(),
 "updated_at" timestamp with time zone not null default now(),
 "recovered_pix_at" timestamp with time zone,
 constraint "technical_manual_banese_reis_cancel_mutation_intent_count_check" CHECK (((cancel_mutation_intent_count >= 0) AND (cancel_mutation_intent_count <= 3))),
 constraint "technical_manual_banese_reiss_receivable_id_canceled_nosso__key" UNIQUE (receivable_id, canceled_nosso_numero),
 constraint "technical_manual_banese_reissue__matricula_id_cycle_number_fkey" FOREIGN KEY (matricula_id, cycle_number) REFERENCES internal_academic.technical_manual_cycle_runs(matricula_id, cycle_number) ON DELETE RESTRICT,
 constraint "technical_manual_banese_reissue_jo_receivable_fingerprint_check" CHECK ((receivable_fingerprint ~ '^[0-9a-f]{64}$'::text)),
 constraint "technical_manual_banese_reissue_job_canceled_nosso_numero_check" CHECK ((canceled_nosso_numero ~ '^[0-9]{9}$'::text)),
 constraint "technical_manual_banese_reissue_jobs_agency_check" CHECK (((agency ~ '^[0-9]{3}$'::text) AND (agency <> '000'::text))),
 constraint "technical_manual_banese_reissue_jobs_convenio_check" CHECK ((convenio ~ '^[0-9]+$'::text)),
 constraint "technical_manual_banese_reissue_jobs_cycle_number_check" CHECK ((cycle_number = ANY (ARRAY[1, 2]))),
 constraint "technical_manual_banese_reissue_jobs_expected_amount_check" CHECK ((expected_amount > (0)::numeric)),
 constraint "technical_manual_banese_reissue_jobs_expected_item_count_check" CHECK ((expected_item_count > 0)),
 constraint "technical_manual_banese_reissue_jobs_original_actor_id_fkey" FOREIGN KEY (original_actor_id) REFERENCES auth.users(id) ON DELETE RESTRICT,
 constraint "technical_manual_banese_reissue_jobs_pkey" PRIMARY KEY (id),
 constraint "technical_manual_banese_reissue_jobs_receivable_id_fkey" FOREIGN KEY (receivable_id) REFERENCES contas_receber(id) ON DELETE RESTRICT,
 constraint "technical_manual_banese_reissue_jobs_status_check" CHECK ((status = ANY (ARRAY['FENCED'::text, 'CANCEL_INTENT'::text, 'CANCEL_CONFIRMED'::text, 'RECOVERED_PIX'::text, 'RESET_COMPLETE'::text])))
);
create table internal_academic.technical_manual_banese_reissue_archive (
 "job_id" uuid not null,
 "receivable_id" uuid not null,
 "matricula_id" uuid not null,
 "turma_id" uuid not null,
 "cycle_number" smallint not null,
 "cycle_request_id" uuid not null,
 "recovery_request_id" uuid not null,
 "original_actor_id" uuid not null,
 "canceled_nosso_numero" text not null,
 "environment" text not null,
 "convenio" text not null,
 "agency" text not null,
 "expected_amount" numeric(14,2) not null,
 "expected_due_date" date not null,
 "receivable_fingerprint" text not null,
 "remote_cancel_status" text not null,
 "remote_cancel_situation_code" integer not null,
 "remote_cancel_confirmed_at" timestamp with time zone not null,
 "remote_cancel_fingerprint" text not null,
 "remote_cancel_observed_pre_canceled" boolean not null,
 "remote_cancel_put_attempted" boolean not null,
 "cancel_mutation_intent_at" timestamp with time zone,
 "gateway_pre_snapshot" jsonb not null,
 "financial_terms_snapshot" jsonb not null,
 "archived_at" timestamp with time zone not null default now(),
 constraint "technical_manual_banese_reis_remote_cancel_situation_code_check" CHECK ((remote_cancel_situation_code = 5)),
 constraint "technical_manual_banese_reiss_environment_convenio_canceled_key" UNIQUE (environment, convenio, canceled_nosso_numero),
 constraint "technical_manual_banese_reissue__financial_terms_snapshot_check" CHECK ((jsonb_typeof(financial_terms_snapshot) = 'object'::text)),
 constraint "technical_manual_banese_reissue_ar_receivable_fingerprint_check" CHECK ((receivable_fingerprint ~ '^[0-9a-f]{64}$'::text)),
 constraint "technical_manual_banese_reissue_arc_canceled_nosso_numero_check" CHECK ((canceled_nosso_numero ~ '^[0-9]{9}$'::text)),
 constraint "technical_manual_banese_reissue_arch_gateway_pre_snapshot_check" CHECK ((jsonb_typeof(gateway_pre_snapshot) = 'object'::text)),
 constraint "technical_manual_banese_reissue_arch_remote_cancel_status_check" CHECK ((remote_cancel_status = ANY (ARRAY['CANCELED'::text, 'CANCELLED'::text]))),
 constraint "technical_manual_banese_reissue_archive_agency_check" CHECK (((agency ~ '^[0-9]{3}$'::text) AND (agency <> '000'::text))),
 constraint "technical_manual_banese_reissue_archive_check" CHECK (((remote_cancel_observed_pre_canceled AND (NOT remote_cancel_put_attempted) AND (cancel_mutation_intent_at IS NULL)) OR ((NOT remote_cancel_observed_pre_canceled) AND remote_cancel_put_attempted AND (cancel_mutation_intent_at IS NOT NULL)))),
 constraint "technical_manual_banese_reissue_archive_convenio_check" CHECK ((convenio ~ '^[0-9]+$'::text)),
 constraint "technical_manual_banese_reissue_archive_environment_check" CHECK ((environment = 'production'::text)),
 constraint "technical_manual_banese_reissue_archive_job_id_fkey" FOREIGN KEY (job_id) REFERENCES internal_academic.technical_manual_banese_reissue_jobs(id) ON DELETE RESTRICT,
 constraint "technical_manual_banese_reissue_archive_pkey" PRIMARY KEY (job_id),
 constraint "technical_manual_banese_reissue_archive_receivable_id_fkey" FOREIGN KEY (receivable_id) REFERENCES contas_receber(id) ON DELETE RESTRICT,
 constraint "technical_manual_banese_reissue_remote_cancel_fingerprint_check" CHECK ((remote_cancel_fingerprint ~ '^[0-9a-f]{64}$'::text))
);
